Done investigating. The chain is clear and consistent across the traces.

```json
{
  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, pa.service_name, pa.span_name, count(*) n, approx_quantile(pa.duration,0.95)/1e6 p95ms FROM abnormal_traces pa WHERE pa.span_name = 'AuthController.createDefaultUser' GROUP BY 1,2,3 UNION ALL SELECT 'norm', pa.service_name, pa.span_name, count(*), approx_quantile(pa.duration,0.95)/1e6 FROM normal_traces pa WHERE pa.span_name = 'AuthController.createDefaultUser' GROUP BY 1,2,3",
          "claim": "createDefaultUser p95 rose from about 75ms in normal to about 280ms in the abnormal period, with a sample count of 46 versus 28."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, span_id, parent_span_id, round(duration/1e6,2) ms, time FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='AuthController.createDefaultUser' ORDER BY duration DESC LIMIT 1) ORDER BY time",
          "claim": "In the slowest auth trace, createDefaultUser runs about 289ms, but its first child (UserRepository.save) starts about 286ms later; the child DB spans total only a few ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95, avg(duration)/1e6 avg FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name IN ('POST /api/v1/users/login','UserController.getToken') GROUP BY 1,2,3",
          "claim": "Auth's login endpoint and getToken stay at about 74ms p95, so only the createDefaultUser path is slow."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, metric, round(avg(value),3) v FROM abnormal_metrics WHERE service_name='ts-auth-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, metric, round(avg(value),3) FROM normal_metrics WHERE service_name='ts-auth-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2,3",
          "claim": "Auth container CPU and CPU-limit utilization are essentially unchanged from normal, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name, c.span_name, count(*) n, approx_quantile(c.duration,0.95)/1e6 p95 FROM abnormal_traces pa JOIN abnormal_traces c ON c.parent_span_id=pa.span_id WHERE pa.service_name='ts-user-service' AND pa.attr_span_kind='Client' GROUP BY 1,2,3 UNION ALL SELECT 'norm', c.service_name, c.span_name, count(*), approx_quantile(c.duration,0.95)/1e6 FROM normal_traces pa JOIN normal_traces c ON c.parent_span_id=pa.span_id WHERE pa.service_name='ts-user-service' AND pa.attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "ts-user-service's outgoing POST to ts-auth-service rose from about 76ms to 231ms p95; the register span rose from 84ms to 719ms."
        }
      ]
    },
    {
      "from": "ts-user-service",
      "to": "ts-admin-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, pa.service_name, pa.span_name, count(*) n, approx_quantile(pa.duration,0.95)/1e6 p95ms FROM abnormal_traces pa WHERE pa.span_name IN ('POST /api/v1/userservice/users/register','POST /api/v1/adminuserservice/users') GROUP BY 1,2,3 UNION ALL SELECT 'norm', pa.service_name, pa.span_name, count(*), approx_quantile(pa.duration,0.95)/1e6 FROM normal_traces pa WHERE pa.span_name IN ('POST /api/v1/userservice/users/register','POST /api/v1/adminuserservice/users') GROUP BY 1,2,3",
          "claim": "The admin-user POST /users and user-service register spans both grew from about 85-90ms to about 300ms and 720ms at p95."
        }
      ]
    },
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, pa.service_name, pa.span_name, count(*) n, approx_quantile(pa.duration,0.95)/1e6 p95ms FROM abnormal_traces pa WHERE pa.service_name='ts-ui-dashboard' AND pa.span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2,3 UNION ALL SELECT 'norm', pa.service_name, pa.span_name, count(*), approx_quantile(pa.duration,0.95)/1e6 FROM normal_traces pa WHERE pa.service_name='ts-ui-dashboard' AND pa.span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2,3",
          "claim": "ts-ui-dashboard's POST /api/v1/adminuserservice/users p95 rose from about 90ms to about 719ms, reaching the user-facing path."
        }
      ]
    }
  ]
}
